function S(a,b,corner,build,upd,credit,opt){var root=mk('div','fsc');var sc={a:a,b:b,root:root,corner:corner,credit:credit||'',upd:upd,opt:opt||{},idx:SCENES.length};var prev=STAGE;STAGE=root;sc.ctx=build(root)||{};STAGE=prev;sc.dk=root.classList.contains('fdk');if(sc.opt.overlay)sc.dk=null;SCENES.push(sc);return sc}
