F.lib={C:C,clamp:clamp,ease:ease,ap:ap,lin:lin,mk:mk,pos:pos,show:show,P:P,PE:PE,K:K,txt:txt,frame:frame,bg:bg,kb:kb,count:count,note:note,S:S,map:map,line:line,city:city,glow:glow,svgEl:svgEl,proj:proj,src:src};
