 var bPlay=el('button',null,'▶ 播放',bar),tm=el('span','ftm','0:00 / '+fmt(dur),bar),sk=el('div','fsk','<i></i>',bar),bRe=el('button',null,'↺ 重播',bar),bCC=el('button',null,'字幕：开',bar),bNext=el('button','fnext',(opts.nextLabel||'下一步')+' ▸',bar);
 function fit(){var aw=W.clientWidth||innerWidth,ah=(W.clientHeight||innerHeight)-64,s=Math.min(aw/1920,ah/1080);vp.style.width=1920*s+'px';vp.style.height=1080*s+'px';root.style.transform='scale('+s+')';W.style.setProperty('--fw',1920*s+'px')}
 fit();addEventListener('resize',fit);
