 function loop(){draw();if(playing)raf=requestAnimationFrame(loop)}
 function play(){big&&big.remove();big=null;endBox&&endBox.remove();endBox=null;au.play().catch(function(){});playing=true;bPlay.textContent='❚❚ 暂停';cancelAnimationFrame(raf);loop();opts.onPlay&&opts.onPlay()}
 function pause(){au.pause();playing=false;bPlay.textContent='▶ 继续';draw()}
 var big=el('div','fbig','<b>▶</b><span>'+(opts.title||'')+'</span>',vp),endBox=null;big.onclick=play;
 bPlay.onclick=function(){playing?pause():play()};bRe.onclick=function(){au.currentTime=0;play()};
 bCC.onclick=function(){var on=root.classList.toggle('nosub');bCC.textContent='字幕：'+(on?'关':'开')};
 sk.onclick=function(e){var r=sk.getBoundingClientRect();au.currentTime=dur*Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));draw()};
 function close(){playing=false;au.pause();cancelAnimationFrame(raf);removeEventListener('resize',fit);removeEventListener('keydown',kd,true);W.remove();opts.onClose&&opts.onClose()}
 bNext.onclick=function(){close();opts.onNext&&opts.onNext()};
 au.onended=function(){playing=false;bPlay.textContent='▶ 播放';au.currentTime=Math.max(0,dur-.05);draw();endBox=el('div','fend',null,vp);var r=el('button',null,'↺ 再看一遍',endBox);r.onclick=function(){au.currentTime=0;play()};var g=el('button','go',(opts.nextLabel||'下一步')+' ▸',endBox);g.onclick=bNext.onclick;opts.onEnd&&opts.onEnd()};
 function kd(e){if(e.key===' '||e.key==='k'){e.preventDefault();e.stopPropagation();playing?pause():play()}else if(e.key==='ArrowLeft'){e.preventDefault();e.stopPropagation();au.currentTime=Math.max(0,au.currentTime-5);draw()}else if(e.key==='ArrowRight'){e.preventDefault();e.stopPropagation();au.currentTime=Math.min(dur,au.currentTime+5);draw()}else if(e.key==='PageDown'||e.key==='Enter'){e.preventDefault();e.stopPropagation();if(!playing&&!big)bNext.onclick();else if(big)play()}}
